/** YEONJI ARCHIVE · one-time mobile GitHub installer. */
import {writeFile, mkdir, unlink} from 'node:fs/promises';
import {join, dirname, resolve, sep} from 'node:path';
import {gunzipSync} from 'node:zlib';
const repo=process.env.GITHUB_REPOSITORY || '';
if (repo.toLowerCase() !== 'bbangshion/yeonji-archive') throw Error('Safety: installer only runs in bbangshion/yeonji-archive');
const data=JSON.parse(gunzipSync(Buffer.from('','base64')).toString('utf8'));
const root=resolve(process.cwd());
function safe(p) {
  if(typeof p !== 'string' || p.startsWith('/') || p.includes('\\') || p.split('/').some(x=>!x || x==='.' || x==='..')) throw Error('Unsafe path: '+p);
  const abs=resolve(root,p);
  if(!abs.startsWith(root+sep)) throw Error('Path escape: '+p);
  return abs;
}
for(const [file,encoded] of data.files) {const target=safe(file);await mkdir(dirname(target),{recursive:true});await writeFile(target,Buffer.from(encoded,'base64'));}
for(const file of data.delete) {await unlink(safe(file)).catch(e=>{if(e.code!=='ENOENT')throw e;});}
console.log(`YEONJI ARCHIVE updated: ${data.files.length} files, ${data.delete.length} former SHION-only files removed.`);
